#pragma once
#include "peripheralhub.hpp"
#include <QWidget>
#include <QPainter>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QComboBox>
#include <QDoubleSpinBox>
#include <QLabel>
#include <QPushButton>
#include <QFileDialog>
#include <QFile>
// A view of captured virtual-time events. Rendering never advances simulation.
class IrVisualizer:public QWidget {
 const PeripheralHub& hub_;QComboBox* history_;QDoubleSpinBox *zoom_,*offset_;QLabel* details_;QWidget* plot_;std::optional<PeripheralHub::IrTrace> trace_;
 class Plot:public QWidget {IrVisualizer* owner_;public:explicit Plot(IrVisualizer* o):owner_(o){setMinimumHeight(175);}void paintEvent(QPaintEvent*)override{owner_->paint(this);}};
 void paint(QWidget* widget){QPainter p(widget);p.fillRect(widget->rect(),QColor("#111c29"));if(!trace_){p.setPen(Qt::white);p.drawText(12,25,"No IR captures yet. Run an IR example.");return;}auto& t=*trace_;const double begin=offset_->value(),span=zoom_->value();const int left=125,width=std::max(1,widget->width()-left-12);p.setPen(QColor("#74889e"));for(int i=0;i<=8;++i){double x=left+i*width/8.;p.drawLine(QPointF(x,12),QPointF(x,145));p.drawText(QPointF(x,165),QString::number(begin+span*i/8.,'f',span<100?1:0));}p.drawText(8,165,"Virtual µs");
 for(int row=0;row<3;++row){int y=30+row*42;p.setPen(Qt::white);p.drawText(6,y+5,row==0?(span/width>2?"GPIO envelope":"GPIO carrier"):row==1?"Optical bursts":"RX active-low");if(row==2&&t.received.pulses.empty()){p.setPen(QColor("#74889e"));p.drawText(left,y+5,"No demodulated capture");continue;}p.setPen(QPen(row==0?QColor("#53c9ff"):row==1?QColor("#f5bf4f"):QColor("#72e0a7"),1.5));QPolygonF points;bool previous=false;for(int x=0;x<=width;++x){double time=begin+span*x/width;bool high=false;if(row==0&&span/width<=2)high=t.emitted.carrier(std::uint64_t(time));else{auto us=std::uint64_t(time);const auto& w=row<2?t.emitted:t.received;for(auto pulse:w.pulses){if(us<pulse.us){high=pulse.mark;break;}us-=pulse.us;}if(row==2)high=!high;}double py=y+(high?-9:9);if(x&&high!=previous)points<<QPointF(left+x,y+(previous?-9:9));points<<QPointF(left+x,py);previous=high;}p.drawPolyline(points);}
 }
 void select(){int index=history_->currentIndex();if(index>=0&&index<int(hub_.irTraces().size()))trace_=hub_.irTraces()[std::size_t(index)];if(!trace_)return;const auto& t=*trace_;auto d=t.decoded;QString text=QString("%1 → %2 · %3 Hz · duty %4% · strength %5 · %6\n").arg(QString::fromStdString(t.source),QString::fromStdString(t.receiver)).arg(t.emitted.hz).arg(t.emitted.duty*100,0,'f',1).arg(t.strength,0,'f',3).arg(QString::fromStdString(t.status));if(d)text+=QString("%1 · address 0x%2 · command 0x%3 · %4 bits%5\n").arg(thinkir::name(d->protocol)).arg(d->address,0,16).arg(d->command,0,16).arg(d->bits).arg(d->repeat?" · repeat":"");text+="Mark / space (µs): ";int count=0;for(auto pulse:t.emitted.pulses){if(++count>12){text+="… (export CSV for all pulses)";break;}text+=QString("%1%2 ").arg(pulse.mark?"M":"S").arg(pulse.us);}details_->setText(text);plot_->update();}
public:
 explicit IrVisualizer(const PeripheralHub& hub):hub_(hub){setObjectName("irVisualizer");auto* layout=new QVBoxLayout(this);history_=new QComboBox;layout->addWidget(history_);details_=new QLabel;details_->setWordWrap(true);layout->addWidget(details_);auto* controls=new QHBoxLayout;zoom_=new QDoubleSpinBox;zoom_->setObjectName("irWindowUs");zoom_->setRange(10,250000);zoom_->setValue(75000);zoom_->setSuffix(" µs window");offset_=new QDoubleSpinBox;offset_->setObjectName("irOffsetUs");offset_->setRange(0,250000);offset_->setSuffix(" µs offset");controls->addWidget(zoom_);controls->addWidget(offset_);auto* save=new QPushButton("Export CSV");controls->addWidget(save);layout->addLayout(controls);plot_=new Plot(this);layout->addWidget(plot_);connect(history_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{select();});for(auto* control:{zoom_,offset_})connect(control,qOverload<double>(&QDoubleSpinBox::valueChanged),this,[this]{plot_->update();});connect(save,&QPushButton::clicked,this,[this]{if(!trace_)return;auto path=QFileDialog::getSaveFileName(this,"Export IR waveform",{},"CSV (*.csv)");if(path.isEmpty())return;QFile file(path);if(!file.open(QIODevice::WriteOnly))return;QByteArray csv="start_us,duration_us,mark,carrier_hz,duty\n";auto at=trace_->start;for(auto p:trace_->emitted.pulses){csv+=QByteArray::number(qulonglong(at))+","+QByteArray::number(p.us)+","+QByteArray::number(p.mark?1:0)+","+QByteArray::number(trace_->emitted.hz)+","+QByteArray::number(trace_->emitted.duty)+"\n";at+=p.us;}file.write(csv);});}
 void refresh(){QSignalBlocker block(history_);const auto count=hub_.irTraces().size();bool changed=history_->count()!=int(count)||(!hub_.irTraces().empty()&&history_->property("lastStart").toULongLong()!=hub_.irTraces().back().start);if(!changed)return;history_->clear();for(const auto& t:hub_.irTraces())history_->addItem(QString("%1 µs · %2 → %3").arg(qulonglong(t.start)).arg(QString::fromStdString(t.source),QString::fromStdString(t.receiver)));history_->setProperty("lastStart",hub_.irTraces().empty()?0:qulonglong(hub_.irTraces().back().start));history_->setCurrentIndex(int(count)-1);if(!count){trace_.reset();details_->clear();plot_->update();}else select();}
};
